using System.Text.Json;
using System.Text.Json.Serialization;
using System.Text.Json.Serialization.Metadata;

// Options with the default reflection-based resolver — resolves any type.
var webOptions = new JsonSerializerOptions(JsonSerializerDefaults.Web);

// 1️⃣  GetTypeInfo<T>() — returns JsonTypeInfo<T> directly, no cast needed.
JsonTypeInfo<Person> personInfo = webOptions.GetTypeInfo<Person>();
Console.WriteLine($"GetTypeInfo<Person> → Type = {personInfo.Type.Name}");

string json = JsonSerializer.Serialize(new Person("Ada", 38), personInfo);
Console.WriteLine($"Serialized: {json}");

// 2️⃣  TryGetTypeInfo<T>() — probe without throwing.
//     With the web defaults (reflection resolver) Person will resolve fine:
if (webOptions.TryGetTypeInfo<Person>(out JsonTypeInfo<Person>? found))
    Console.WriteLine($"TryGetTypeInfo<Person> succeeded → {found!.Type.Name}");
else
    Console.WriteLine("TryGetTypeInfo<Person> returned false");

// Now use options with a source-gen context that only knows about Person.
// Asking for int[] metadata will return false instead of throwing.
var strictOptions = new JsonSerializerOptions
{
    TypeInfoResolver = PersonContext.Default
};

if (strictOptions.TryGetTypeInfo<int[]>(out JsonTypeInfo<int[]>? arrayInfo))
    Console.WriteLine($"TryGetTypeInfo<int[]> succeeded → {arrayInfo!.Type.Name}");
else
    Console.WriteLine("TryGetTypeInfo<int[]> returned false (not in the source-gen context)");

// Record used by the demo
public record Person(string Name, int Age);

